        # Calculate summary statistics
        returns = self.data['Daily_Return'].dropna()

        report = {
            'analysis_info': {
                'ticker': self.ticker,
                'analysis_period': {
                    'start_date': self.data.index[0].strftime('%Y-%m-%d'),
                    'end_date': self.data.index[-1].strftime('%Y-%m-%d'),
                    'trading_days': len(self.data)
                },
                'z_score_threshold': self.z_threshold,
                'generated_at': datetime.now().isoformat()
            },
            'summary_statistics': {
                'mean_daily_return': round(returns.mean() * 100, 4),
                'std_daily_return': round(returns.std() * 100, 4),
                'min_daily_return': round(returns.min() * 100, 2),
                'max_daily_return': round(returns.max() * 100, 2),
                'total_anomalies': len(self.anomalies)
            },
            'anomalous_days': self.anomalies,
            'all_trading_days': []
        }

        # Add all trading days data
        for date, row in self.data.iterrows():
            day_data = {
                'date': date.strftime('%Y-%m-%d'),
                'close_price': round(row['Close'], 2),
                'daily_return': round(row['Daily_Return'] * 100, 2) if not pd.isna(row['Daily_Return']) else None,
                'z_score': round(row['Z_Score'], 3) if not pd.isna(row['Z_Score']) else None,
