#!/usr/bin/env python3
"""
META Stock Anomaly Detection

This script fetches META stock data for the last 14 days,
detects anomalous trading days using Z-score analysis,
and generates comprehensive reports in multiple formats.
"""

import yfinance as yf
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
from datetime import datetime, timedelta
import json
import sys
from typing import Dict, List, Tuple, Optional


class StockAnomalyDetector:
    """Detects anomalies in stock trading data using Z-score analysis."""

    def __init__(self, ticker: str = 'META', days: int = 14, z_threshold: float = 2.0):
        self.ticker = ticker
        self.days = days
        self.z_threshold = z_threshold
        self.data: Optional[pd.DataFrame] = None
        self.anomalies: List[Dict] = []

    def fetch_stock_data(self) -> bool:
        """Fetch stock data from yfinance with error handling."""
        try:
            end_date = datetime.now()
            start_date = end_date - timedelta(days=self.days + 5)  # Extra days for weekends

            print(f"Fetching {self.ticker} stock data from {start_date.date()} to {end_date.date()}...")

            # Fetch data with error handling
            stock = yf.Ticker(self.ticker)
            self.data = stock.history(start=start_date, end=end_date)

            if self.data.empty:
                raise ValueError(f"No data found for ticker {self.ticker}")

            # Keep only the last 14 trading days
            self.data = self.data.tail(self.days)

            print(f"Successfully fetched {len(self.data)} trading days of data")
            return True

        except Exception as e:
            print(f"Error fetching stock data: {str(e)}")
            return False

    def calculate_daily_returns(self) -> None:
        """Calculate daily returns and Z-scores."""
        if self.data is None or self.data.empty:
            raise ValueError("No stock data available. Please fetch data first.")

        # Calculate daily returns (percentage change)
        self.data['Daily_Return'] = self.data['Close'].pct_change()

        # Remove NaN values (first day has no previous day for comparison)
        returns = self.data['Daily_Return'].dropna()

        if len(returns) < 2:
            raise ValueError("Insufficient data to calculate statistics")

        # Calculate statistics
        mean_return = returns.mean()
        std_return = returns.std()

        if std_return == 0:
            print("Warning: Standard deviation is zero. All returns are identical.")
            self.data['Z_Score'] = 0
        else:
            # Calculate Z-scores
            self.data['Z_Score'] = (self.data['Daily_Return'] - mean_return) / std_return

        print(f"Daily returns calculated. Mean: {mean_return:.4f}, Std: {std_return:.4f}")

    def detect_anomalies(self) -> None:
        """Detect anomalous trading days based on Z-score threshold."""
        if self.data is None:
            raise ValueError("No data available for anomaly detection")

        # Find anomalies where |Z-score| > threshold
        anomaly_mask = abs(self.data['Z_Score']) > self.z_threshold
        anomaly_data = self.data[anomaly_mask]

        self.anomalies = []
        for date, row in anomaly_data.iterrows():
            anomaly = {
                'date': date.strftime('%Y-%m-%d'),
                'close_price': round(row['Close'], 2),
                'daily_return': round(row['Daily_Return'] * 100, 2),  # Convert to percentage
                'z_score': round(row['Z_Score'], 3),
                'anomaly_type': 'Positive' if row['Z_Score'] > 0 else 'Negative'
            }
            self.anomalies.append(anomaly)

        print(f"Detected {len(self.anomalies)} anomalous trading days")

    def generate_chart(self, filename: str = 'anomalies.png') -> None:
        """Generate and save a matplotlib chart highlighting anomalies."""
        if self.data is None:
            raise ValueError("No data available for chart generation")

        fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(12, 10))

        # Plot 1: Stock price with anomalous days highlighted
        dates = self.data.index
        prices = self.data['Close']

        ax1.plot(dates, prices, 'b-', linewidth=2, label='Close Price')

        # Highlight anomalous days
        anomaly_mask = abs(self.data['Z_Score']) > self.z_threshold
        if anomaly_mask.any():
            anomaly_dates = self.data[anomaly_mask].index
            anomaly_prices = self.data[anomaly_mask]['Close']
            ax1.scatter(anomaly_dates, anomaly_prices, color='red', s=100, 
                       label='Anomalous Days', zorder=5)

        ax1.set_title(f'{self.ticker} Stock Price - Last {self.days} Trading Days', fontsize=14, fontweight='bold')
        ax1.set_ylabel('Price ($)', fontsize=12)
        ax1.legend()
        ax1.grid(True, alpha=0.3)

        # Format x-axis dates
        ax1.xaxis.set_major_formatter(mdates.DateFormatter('%m/%d'))
        ax1.xaxis.set_major_locator(mdates.DayLocator(interval=2))

        # Plot 2: Daily returns with Z-score threshold lines
        returns_pct = self.data['Daily_Return'] * 100  # Convert to percentage

        ax2.bar(dates, returns_pct, alpha=0.7, label='Daily Returns')

        # Highlight anomalous days
        if anomaly_mask.any():
            anomaly_returns = self.data[anomaly_mask]['Daily_Return'] * 100
            ax2.bar(anomaly_dates, anomaly_returns, color='red', alpha=0.8, 
                   label='Anomalous Returns')

        # Add Z-score threshold lines (approximate)
        if len(self.data['Daily_Return'].dropna()) > 1:
            mean_return = self.data['Daily_Return'].mean() * 100
            std_return = self.data['Daily_Return'].std() * 100

            upper_threshold = mean_return + (self.z_threshold * std_return)
            lower_threshold = mean_return - (self.z_threshold * std_return)

            ax2.axhline(y=upper_threshold, color='orange', linestyle='--', 
                       label=f'Z-score = +{self.z_threshold}')
            ax2.axhline(y=lower_threshold, color='orange', linestyle='--', 
                       label=f'Z-score = -{self.z_threshold}')

        ax2.set_title('Daily Returns with Anomaly Thresholds', fontsize=14, fontweight='bold')
        ax2.set_xlabel('Date', fontsize=12)
        ax2.set_ylabel('Daily Return (%)', fontsize=12)
        ax2.legend()
        ax2.grid(True, alpha=0.3)

        # Format x-axis dates
        ax2.xaxis.set_major_formatter(mdates.DateFormatter('%m/%d'))
        ax2.xaxis.set_major_locator(mdates.DayLocator(interval=2))

        plt.tight_layout()
        plt.savefig(filename, dpi=300, bbox_inches='tight')
        plt.close()

        print(f"Chart saved as {filename}")

