class StockAnomalyDetector:
    """Detects anomalies in stock trading data using Z-score analysis."""

    def __init__(self, ticker: str = 'META', days: int = 14, z_threshold: float = 2.0):
        self.ticker = ticker
        self.days = days
        self.z_threshold = z_threshold
        self.data: Optional[pd.DataFrame] = None
        self.anomalies: List[Dict] = []

    def fetch_stock_data(self) -> bool:
        """Fetch stock data from yfinance with error handling."""
        try:
            end_date = datetime.now()
            start_date = end_date - timedelta(days=self.days + 5)  # Extra days for weekends

            print(f"Fetching {self.ticker} stock data from {start_date.date()} to {end_date.date()}...")

            # Fetch data with error handling
            stock = yf.Ticker(self.ticker)
            self.data = stock.history(start=start_date, end=end_date)

            if self.data.empty:
                raise ValueError(f"No data found for ticker {self.ticker}")

            # Keep only the last 14 trading days
            self.data = self.data.tail(self.days)

            print(f"Successfully fetched {len(self.data)} trading days of data")
            return True

        except Exception as e:
            print(f"Error fetching stock data: {str(e)}")
            return False

    def calculate_daily_returns(self) -> None:
        """Calculate daily returns and Z-scores."""
        if self.data is None or self.data.empty:
            raise ValueError("No stock data available. Please fetch data first.")

        # Calculate daily returns (percentage change)
        self.data['Daily_Return'] = self.data['Close'].pct_change()

        # Remove NaN values (first day has no previous day for comparison)
        returns = self.data['Daily_Return'].dropna()

        if len(returns) < 2:
            raise ValueError("Insufficient data to calculate statistics")

        # Calculate statistics
        mean_return = returns.mean()
        std_return = returns.std()

        if std_return == 0:
            print("Warning: Standard deviation is zero. All returns are identical.")
            self.data['Z_Score'] = 0
        else:
            # Calculate Z-scores
            self.data['Z_Score'] = (self.data['Daily_Return'] - mean_return) / std_return

        print(f"Daily returns calculated. Mean: {mean_return:.4f}, Std: {std_return:.4f}")

    def detect_anomalies(self) -> None:
        """Detect anomalous trading days based on Z-score threshold."""
        if self.data is None:
            raise ValueError("No data available for anomaly detection")

        # Find anomalies where |Z-score| > threshold
        anomaly_mask = abs(self.data['Z_Score']) > self.z_threshold
        anomaly_data = self.data[anomaly_mask]

        self.anomalies = []
        for date, row in anomaly_data.iterrows():
            anomaly = {
                'date': date.strftime('%Y-%m-%d'),
                'close_price': round(float(row['Close']), 2),
                'daily_return': round(float(row['Daily_Return']) * 100, 2),  # Convert to percentage
                'z_score': round(float(row['Z_Score']), 3),
                'anomaly_type': 'Positive' if row['Z_Score'] > 0 else 'Negative'
            }
            self.anomalies.append(anomaly)

        print(f"Detected {len(self.anomalies)} anomalous trading days")

