            else:
                print("No anomalous days detected.")

    print("\nGenerated files:")
    print("  - anomalies.png (visualization chart)")
    print("  - anomaly_report.json (detailed JSON report)")
    print("  - anomaly_report.html (summary HTML report)")

    return True

